// ===========================================================================
// B3_Lib.fs
// ===========================================================================
/*
 * B3 folding bed stair: shared helpers and derived positions.
 * Nothing to adjust here; the numbers live in B3 Parameters.
 */

// Which tread: n = 0 is the hook-on step, 1 the middle tread, 2 the top tread.
export const HOOK_STEP = 0;
export const TREAD_MIDDLE = 1;
export const TREAD_TOP = 2;

export const RGB_ALU = [0.78, 0.80, 0.83];
export const RGB_ALU_DARK = [0.55, 0.60, 0.66];
export const RGB_STEP = [0.62, 0.56, 0.77];
export const RGB_STEEL = [0.36, 0.41, 0.44];
export const RGB_TUBE = [0.70, 0.72, 0.76];
export const RGB_REF = [0.85, 0.75, 0.57];

// ---------------------------------------------------------------------------
// Derived positions
// ---------------------------------------------------------------------------
// Tread top T.
export function b3T(n is number) returns ValueWithUnits
{
    return (n + 1) * RISE;
}

// Start of the tread's going along x: top 0, middle 6, step 12.
export function b3GoingX(n is number) returns ValueWithUnits
{
    return (2 - n) * GOING;
}

// Outer faces of the two ears in a going (back, front).
export function b3EarFaces(n is number) returns array
{
    const xg = b3GoingX(n);
    return [xg + EAR_X0, xg + GOING - EAR_X0];
}

// The two ears' x ranges, each PLATE_T thick inboard of its outer face.
export function b3EarRanges(n is number) returns array
{
    const f = b3EarFaces(n);
    return [[f[0], f[0] + PLATE_T], [f[1] - PLATE_T, f[1]]];
}

// ---------------------------------------------------------------------------
// Page coordinates to Onshape
// ---------------------------------------------------------------------------
// The page's x, y, z are a left-handed set as installed (facing the bed-end
// wall, the cabinet is on the right), so the page's y runs along Onshape's -Y.
// Every helper below takes page coordinates.
export function b3V(p is Vector) returns Vector
{
    return vector(p[0], -p[1], p[2]);
}

// ---------------------------------------------------------------------------
// Mate connectors
// ---------------------------------------------------------------------------
// Joints between parts, in page coordinates: each is the frame where two
// parts' mate connectors meet when the stair is open. Pivot and axle frames
// have z along -x (toward the bed end) and x along y.
export function b3Joint(origin is Vector, zAxis is Vector, xAxis is Vector) returns map
{
    return { "origin" : origin, "zAxis" : zAxis, "xAxis" : xAxis };
}

export function b3AxleJoint(x is ValueWithUnits, y is ValueWithUnits, z is ValueWithUnits) returns map
{
    return b3Joint(vector(x, y, z), vector(-1, 0, 0), vector(0, 1, 0));
}

// On the panel face (z out into the room, x along the cabinet).
export function b3PanelJoint(x is ValueWithUnits, z is ValueWithUnits) returns map
{
    return b3Joint(vector(x, 0 * inch, z), vector(0, 1, 0), vector(1, 0, 0));
}

// Tread n's cabinet and outer axles, at the axle's bed-end tip.
export function b3CabAxleJoint(n is number) returns map
{
    return b3AxleJoint(b3GoingX(n) + TREAD_AXLE_X0, CAB_AXLE_Y, b3T(n) - CAB_AXLE_DROP);
}

export function b3OutAxleJoint(n is number) returns map
{
    return b3AxleJoint(b3GoingX(n) + TREAD_AXLE_X0, OUT_AXLE_Y, b3T(n) - OUT_AXLE_DROP);
}

// Bracket n on the panel: the web's bottom corner at the bed end.
export function b3BracketJoint(n is number) returns map
{
    return b3PanelJoint(b3EarFaces(n)[0], b3T(n) - BRACKET_TOP_DROP - BRACKET_H);
}

// Tread n's rail bracket is the same part as its cabinet bracket, turned
// half a turn about a vertical axis and lowered so its axle hole lands on the
// outer axle line. This moves a joint on the cabinet bracket to the same spot
// on the rail bracket.
export function b3OnRail(n is number, joint is map) returns map
{
    const xg = b3GoingX(n);
    const p = joint.origin;
    const z = joint.zAxis;
    const x = joint.xAxis;
    return b3Joint(vector(2 * xg + GOING - p[0], OUT_AXLE_Y + CAB_AXLE_Y - p[1], p[2] + CAB_AXLE_DROP - OUT_AXLE_DROP),
        vector(-z[0], -z[1], z[2]), vector(-x[0], -x[1], x[2]));
}

// Bracket n's web on the rail's inner face.
export function b3RailBracketJoint(n is number) returns map
{
    return b3OnRail(n, b3BracketJoint(n));
}

// The bracket's axle seen from its other end, so that on the rail it matches
// the tread's outer axle joint: b3OnRail(n, b3BracketAxleTurnedJoint(n)) is
// b3OutAxleJoint(n).
export function b3BracketAxleTurnedJoint(n is number) returns map
{
    return b3Joint(vector(b3GoingX(n) + GOING - TREAD_AXLE_X0, CAB_AXLE_Y, b3T(n) - CAB_AXLE_DROP),
        vector(1, 0, 0), vector(0, -1, 0));
}

// Screw hole k in bracket n's web, on the ear side, z along the screw.
export function b3BracketScrewJoint(n is number, k is number) returns map
{
    return b3Joint(vector(b3GoingX(n) + SCREW_X[k], PLATE_T, b3T(n) - SCREW_DROP), vector(0, -1, 0), vector(1, 0, 0));
}

// The nut on the rail's outer face for screw k of tread n's rail bracket.
export function b3RailNutJoint(n is number, k is number) returns map
{
    const hole = b3OnRail(n, b3BracketScrewJoint(n, k)).origin;
    return b3Joint(vector(hole[0], RAIL_Y + PLATE_T, hole[2]), vector(0, 1, 0), vector(1, 0, 0));
}

// Front angle on the panel: its bottom front corner.
export function b3FrontAngleJoint() returns map
{
    return b3PanelJoint(FA_X1, FA_BOTTOM_Z);
}

// Step ledge on the panel: the leg's bottom corner at the bed end.
export function b3StepLedgeJoint() returns map
{
    return b3PanelJoint(0 * inch, LEDGE_TOP_Z - LEDGE_LEG_H);
}

// Tread n's stop pins, on the bracket ear's inside face, z along the pin.
export function b3StopPinJoint(n is number, front is boolean) returns map
{
    const r = b3EarRanges(n);
    const p = vector(front ? r[1][0] : r[0][1], STOP_PIN_Y, b3T(n) - STOP_PIN_DROP);
    return b3Joint(p, vector(front ? 1 : -1, 0, 0), vector(0, 1, 0));
}

// Step clip on the rail's inner face, at the clip's bottom corner on the bed-end side.
export function b3StepClipJoint() returns map
{
    return b3Joint(vector(CLIP_X0, RAIL_Y, CLIP_Z0), vector(0, -1, 0), vector(1, 0, 0));
}

export function b3StepCabAxleJoint() returns map
{
    return b3AxleJoint(STEP_AXLE_X0, STEP_CAB_AXLE_Y, STEP_CAB_AXLE_Z);
}

export function b3StepOutAxleJoint() returns map
{
    return b3AxleJoint(STEP_AXLE_X0, STEP_OUT_AXLE_Y, STEP_OUT_AXLE_Z);
}

// A mate connector named mcName on the part partName (the bodies in owner),
// at a joint. The assembly script finds it by its "b3Mc" attribute; an
// assembly mate names it by its id, joined with dots.
export function b3Mc(context is Context, id is Id, owner is Query, partName is string, mcName is string, joint is map)
{
    opMateConnector(context, id, {
                "coordSystem" : coordSystem(b3V(joint.origin), b3V(joint.xAxis), b3V(joint.zAxis)),
                "owner" : owner
            });
    var fullId = id[0];
    for (var i = 1; i < size(id); i += 1)
    {
        fullId = fullId ~ "." ~ id[i];
    }
    setAttribute(context, { "entities" : qCreatedBy(id, EntityType.BODY), "name" : "b3Mc",
                "attribute" : { "part" : partName, "name" : mcName, "featureId" : fullId } });
}

// ---------------------------------------------------------------------------
// Sketch planes and prisms
// ---------------------------------------------------------------------------
// Sketch (u, v) = (y, z), extruded along -x.
export function b3PlaneYZ(x is ValueWithUnits) returns Plane
{
    return plane(b3V(vector(x, 0 * inch, 0 * inch)), vector(-1, 0, 0), b3V(vector(0, 1, 0)));
}

// Sketch (u, v) = (x, z), extruded along +y.
export function b3PlaneXZ(y is ValueWithUnits) returns Plane
{
    return plane(b3V(vector(0 * inch, y, 0 * inch)), b3V(vector(0, 1, 0)), vector(1, 0, 0));
}

// Sketch (u, v) = (x, y), extruded along -z.
export function b3PlaneXY(z is ValueWithUnits) returns Plane
{
    return plane(vector(0 * inch, 0 * inch, z), vector(0, 0, -1), vector(1, 0, 0));
}

// Closed loop through 2D points. An entry {"mid" : p, "end" : q} draws an arc
// from the previous point through p to q. The loop closes with a line.
export function b3SketchLoop(sketch is Sketch, prefix is string, path is array)
{
    const first = path[0];
    var cur = first;
    for (var i = 1; i <= size(path); i += 1)
    {
        const item = i < size(path) ? path[i] : first;
        if (item is map)
        {
            skArc(sketch, prefix ~ "a" ~ toString(i), { "start" : cur, "mid" : item.mid, "end" : item.end });
            cur = item.end;
        }
        else
        {
            skLineSegment(sketch, prefix ~ "l" ~ toString(i), { "start" : cur, "end" : item });
            cur = item;
        }
    }
}

// Extrudes a 2D outline by depth. Each hole is {"center" : p, "dia" : d}
// or a closed path like the outline.
export function b3Prism(context is Context, id is Id, frame is Plane, path is array, holes is array, depth is ValueWithUnits)
{
    const sketchId = id + "sketch";
    const sketch = newSketchOnPlane(context, sketchId, { "sketchPlane" : frame });
    b3SketchLoop(sketch, "outline", path);
    for (var i = 0; i < size(holes); i += 1)
    {
        const h = holes[i];
        if (h is map)
        {
            skCircle(sketch, "hole" ~ toString(i), { "center" : h.center, "radius" : h.dia / 2 });
        }
        else
        {
            b3SketchLoop(sketch, "hole" ~ toString(i), h);
        }
    }
    skSolve(sketch);
    opExtrude(context, id + "extrude", {
                "entities" : qSketchRegion(sketchId, true),
                "direction" : frame.normal,
                "endBound" : BoundingType.BLIND,
                "endDepth" : depth
            });
    opDeleteBodies(context, id + "cleanup", { "entities" : qCreatedBy(sketchId, EntityType.BODY) });
}

// Outline in (y, z), from x0 to x1.
export function b3PrismYZ(context is Context, id is Id, path is array, holes is array, x0 is ValueWithUnits, x1 is ValueWithUnits)
{
    b3Prism(context, id, b3PlaneYZ(x1), path, holes, x1 - x0);
}

// Outline in (x, z), from y0 to y1.
export function b3PrismXZ(context is Context, id is Id, path is array, holes is array, y0 is ValueWithUnits, y1 is ValueWithUnits)
{
    b3Prism(context, id, b3PlaneXZ(y0), path, holes, y1 - y0);
}

// Outline in (x, y), from z0 to z1.
export function b3PrismXY(context is Context, id is Id, path is array, holes is array, z0 is ValueWithUnits, z1 is ValueWithUnits)
{
    b3Prism(context, id, b3PlaneXY(z1), path, holes, z1 - z0);
}

export function b3Box(context is Context, id is Id, lo is Vector, hi is Vector)
{
    fCuboid(context, id, { "corner1" : b3V(lo), "corner2" : b3V(hi) });
}

// Cylinder along x.
export function b3CylX(context is Context, id is Id, y is ValueWithUnits, z is ValueWithUnits,
    x0 is ValueWithUnits, x1 is ValueWithUnits, dia is ValueWithUnits)
{
    fCylinder(context, id, { "bottomCenter" : b3V(vector(x0, y, z)), "topCenter" : b3V(vector(x1, y, z)), "radius" : dia / 2 });
}

// Tube along x, x0 < x1, with a bore.
export function b3TubeX(context is Context, id is Id, y is ValueWithUnits, z is ValueWithUnits,
    x0 is ValueWithUnits, x1 is ValueWithUnits, dia is ValueWithUnits, bore is ValueWithUnits)
{
    b3CylX(context, id + "outside", y, z, x0, x1, dia);
    b3CylX(context, id + "bore", y, z, x0 - 1 * millimeter, x1 + 1 * millimeter, bore);
    opBoolean(context, id + "cut", { "tools" : b3Solids(id + "bore"), "targets" : b3Solids(id + "outside"),
                "operationType" : BooleanOperationType.SUBTRACTION });
}

// ---------------------------------------------------------------------------
// 2D shapes
// ---------------------------------------------------------------------------
export function b3Rect(u0 is ValueWithUnits, v0 is ValueWithUnits, u1 is ValueWithUnits, v1 is ValueWithUnits) returns array
{
    return [vector(u0, v0), vector(u1, v0), vector(u1, v1), vector(u0, v1)];
}

// Rounds the corner p, between the edges to a and to b, with radius r: the
// path entries from the tangent point on pa, around the arc, to the tangent
// point on pb. Works for outside and inside corners alike.
export function b3Corner(a is Vector, p is Vector, b is Vector, r is ValueWithUnits) returns array
{
    const ua = (a - p) / norm(a - p);
    const ub = (b - p) / norm(b - p);
    const half = acos(dot(ua, ub)) / 2;
    const bisector = (ua + ub) / norm(ua + ub);
    const center = p + bisector * (r / sin(half));
    return [p + ua * (r / tan(half)), { "mid" : center - bisector * r, "end" : p + ub * (r / tan(half)) }];
}

// Closed polygon with corner i rounded to radii[i] (0 leaves it sharp). Each
// corner's tangent points must stay on its two edges.
export function b3Rounded(points is array, radii is array) returns array
{
    const n = size(points);
    var path = [];
    for (var i = 0; i < n; i += 1)
    {
        if (radii[i] is number || radii[i] <= 0 * inch)
        {
            path = append(path, points[i]);
        }
        else
        {
            path = concatenateArrays([path, b3Corner(points[(i + n - 1) % n], points[i], points[(i + 1) % n], radii[i])]);
        }
    }
    return path;
}

export function b3Hole(u is ValueWithUnits, v is ValueWithUnits, dia is ValueWithUnits) returns map
{
    return { "center" : vector(u, v), "dia" : dia };
}

// Obround slot centered on c, l long along u and h tall along v.
export function b3Slot(c is Vector, l is ValueWithUnits, h is ValueWithUnits) returns array
{
    const r = h / 2;
    const a = l / 2 - r;
    return [
            vector(c[0] - a, c[1] + r),
            { "mid" : vector(c[0] - a - r, c[1]), "end" : vector(c[0] - a, c[1] - r) },
            vector(c[0] + a, c[1] - r),
            { "mid" : vector(c[0] + a + r, c[1]), "end" : vector(c[0] + a, c[1] + r) }
        ];
}

// Keyhole: KEYHOLE_DIA hole centered (u, vHole), with a KEYHOLE_SLOT_W slot
// running down to a round end centered at vEnd.
export function b3Keyhole(u is ValueWithUnits, vHole is ValueWithUnits, vEnd is ValueWithUnits) returns array
{
    const big = KEYHOLE_DIA / 2;
    const h = KEYHOLE_SLOT_W / 2;
    const meet = vHole - sqrt(big * big - h * h);
    return [
            vector(u - h, vEnd),
            { "mid" : vector(u, vEnd - h), "end" : vector(u + h, vEnd) },
            vector(u + h, meet),
            { "mid" : vector(u, vHole + big), "end" : vector(u - h, meet) }
        ];
}

// Hook-shaped bracket ear in (y, z). The ear runs from the root face yRoot
// to yFar, over z zLo to zHi; above that the hook (yHookIn to yFar) rises to
// a round top of radius EAR_HOOK_R on the axle (axY, axZ). The bottom outer
// corner and the hook notch are rounded.
export function b3EarOutline(yRoot is ValueWithUnits, yFar is ValueWithUnits, yHookIn is ValueWithUnits,
    zLo is ValueWithUnits, zHi is ValueWithUnits, axY is ValueWithUnits, axZ is ValueWithUnits) returns array
{
    const root = vector(yRoot, zLo);
    const notch = vector(yHookIn, zHi);
    return concatenateArrays([
                [root],
                b3Corner(root, vector(yFar, zLo), vector(yFar, axZ), EAR_CORNER_R),
                [vector(yFar, axZ), { "mid" : vector(axY, axZ + EAR_HOOK_R), "end" : vector(yHookIn, axZ) }],
                b3Corner(vector(yHookIn, axZ), notch, vector(yRoot, zHi), EAR_NOTCH_R),
                [vector(yRoot, zHi)]
            ]);
}

// Flange bent off the plate along the edge p -> q (in x, z, plate on the left
// of travel), PLATE_T thick inward from the edge, from y0 out to yTip. Its free
// corners at p and q are rounded to rP and rQ.
export function b3Flange(context is Context, id is Id, p is Vector, q is Vector, y0 is ValueWithUnits, yTip is ValueWithUnits,
    rP is ValueWithUnits, rQ is ValueWithUnits)
{
    const d = (q - p) / norm(q - p);
    const len = norm(q - p);
    // Sketch (u, v) = (distance along the edge from p, -y), extruded into the plate.
    const edgePlane = plane(b3V(vector(p[0], 0 * inch, p[1])), vector(-d[1], 0, d[0]), vector(d[0], 0, d[1]));
    const outline = b3Rounded(b3Rect(0 * inch, -yTip, len, -y0), [rP, rQ, 0, 0]);
    b3Prism(context, id, edgePlane, outline, [], PLATE_T);
}

// ---------------------------------------------------------------------------
// Tray (treads and hook-on step): skin plus two lips bent down at the x ends,
// as a sheet-metal part. Holes are in (y, z) and go through both lips. Both
// bottom corners of each lip are rounded to LIP_CORNER_R.
// ---------------------------------------------------------------------------
export function b3Tray(context is Context, id is Id, x0 is ValueWithUnits, top is ValueWithUnits, holes is array)
{
    const y0 = TRAY_Y0;
    const y1 = TRAY_Y0 + TRAY_W;
    const x1 = x0 + TRAY_D;
    const zb = top - LIP;
    const lip = b3Rounded([vector(y0, top), vector(y1, top), vector(y1, zb), vector(y0, zb)],
        [0, 0, LIP_CORNER_R, LIP_CORNER_R]);
    b3Box(context, id + "skin", vector(x0, y0, top - SHEET_T), vector(x1, y1, top));
    b3PrismYZ(context, id + "lipBack", lip, holes, x0, x0 + SHEET_T);
    b3PrismYZ(context, id + "lipFront", lip, holes, x1 - SHEET_T, x1);
    b3Union(context, id + "join", b3Solids(id));
    const ym = (y0 + y1) / 2;
    b3SheetMetal(context, id + "sm", b3Solids(id), [
                vector((x0 + x1) / 2, ym, top),
                vector(x0, ym, top - LIP / 2),
                vector(x1, ym, top - LIP / 2)
            ], SHEET_T, BEND_R_SHEET, K_SHEET);
}

// ---------------------------------------------------------------------------
// Sheet metal
// ---------------------------------------------------------------------------
// On the flat pattern of a 90 degree bend of thickness t, inside radius r and
// K-factor k: how far the bend line (the middle of the bend) sits inside the
// wall's outside face as modeled.
export function b3BendLine(t is ValueWithUnits, r is ValueWithUnits, k is number) returns ValueWithUnits
{
    return r + t - (PI / 4) * (r + k * t);
}

// How far inside the outside face a bend relief has to reach: SendCutSend's
// r + t + RELIEF_EXTRA past the bend line.
export function b3ReliefDepth(t is ValueWithUnits, r is ValueWithUnits, k is number) returns ValueWithUnits
{
    return b3BendLine(t, r, k) + r + t + RELIEF_EXTRA;
}

// How far inside the outside face a bare edge past a relief sits, so that the
// bend line runs clear of it.
export function b3BareInset(t is ValueWithUnits, r is ValueWithUnits, k is number) returns ValueWithUnits
{
    return b3BendLine(t, r, k) + RELIEF_CLEAR;
}

// Turns body, a solid modeled to the outside of its bends with sharp bends,
// into an Onshape sheet-metal part. outside lists a point (page coordinates)
// inside each outside face: the base wall first, then each wall bent off it.
// The edges between the base and the others become bends of inside radius r;
// any edge between two of the others becomes a rip with a round corner relief
// of SendCutSend's size. The thickness t goes inward, so the outside faces
// stay put. Bend reliefs are cut in the model; if Onshape adds one of its own,
// it is as deep as SendCutSend's.
export function b3SheetMetal(context is Context, id is Id, body is Query, outside is array,
    t is ValueWithUnits, r is ValueWithUnits, k is number)
{
    const faces = qOwnedByBody(body, EntityType.FACE);
    var walls = [];
    for (var p in outside)
    {
        const wall = qContainsPoint(faces, b3V(p));
        if (size(evaluateQuery(context, wall)) != 1)
        {
            throw regenError("B3: expected one outside face at " ~ toString(p / inch) ~ " in");
        }
        walls = append(walls, wall);
    }
    const baseEdges = qAdjacent(walls[0], AdjacencyType.EDGE, EntityType.EDGE);
    var bends = [];
    for (var i = 1; i < size(walls); i += 1)
    {
        bends = append(bends, qIntersection([baseEdges, qAdjacent(walls[i], AdjacencyType.EDGE, EntityType.EDGE)]));
    }
    sheetMetalStart(context, id, {
                "process" : SMProcessType.CONVERT,
                "partToConvert" : body,
                "facesToExclude" : qSubtraction(faces, qUnion(walls)),
                "bends" : qUnion(bends),
                "thickness" : t,
                "radius" : r,
                "kFactor" : k,
                "oppositeDirection" : true,
                "defaultCornerStyle" : SMCornerStrategyType.SIZED_ROUND,
                "defaultRoundReliefDiameter" : 2 * (r + t + RELIEF_EXTRA),
                "defaultBendReliefStyle" : SMBendStrategyType.RECTANGLE,
                "defaultBendReliefDepthScale" : b3OnshapeReliefScale(t, r, k),
                "defaultBendReliefScale" : RELIEF_W_SCALE
            });
}

// Onshape's rectangular bend relief at depth scale 1 reaches half the bend
// allowance plus half the relief width past the bend line, and each step of
// the scale above 1 adds r. This is the scale that reaches r + t + RELIEF_EXTRA.
function b3OnshapeReliefScale(t is ValueWithUnits, r is ValueWithUnits, k is number) returns number
{
    const base = (PI / 4) * (r + k * t) + RELIEF_W_SCALE * t / 2;
    return min(5, 1 + max(0 * inch, r + t + RELIEF_EXTRA - base) / r);
}

// Bend relief where a bend stops at p, short of the end of the edge it runs
// along: a slot in the wall that carries on, RELIEF_W_SCALE * t wide along the
// edge (direction along, away from the bend) and b3ReliefDepth deep (direction
// inward, into the wall). Past the slot, the bare edge is cut back to
// b3BareInset for bareLength from p, so the bend line runs clear of it. A 2D
// outline to cut with b3Prism*.
export function b3ReliefPath(p is Vector, along is Vector, inward is Vector, t is ValueWithUnits, r is ValueWithUnits, k is number,
    bareLength is ValueWithUnits) returns array
{
    const a = along / norm(along);
    const n = inward / norm(inward);
    const w = RELIEF_W_SCALE * t;
    const d = b3ReliefDepth(t, r, k);
    const e = b3BareInset(t, r, k);
    const out = n * (-0.05 * inch);
    if (bareLength <= w)
    {
        return [p + out, p + a * w + out, p + a * w + n * d, p + n * d];
    }
    return [p + out, p + a * bareLength + out, p + a * bareLength + n * e, p + a * w + n * e, p + a * w + n * d, p + n * d];
}

export function b3Subtract(context is Context, id is Id, targets is Query, tools is Query)
{
    opBoolean(context, id, { "tools" : tools, "targets" : targets, "operationType" : BooleanOperationType.SUBTRACTION });
}

// ---------------------------------------------------------------------------
// Booleans and finishing
// ---------------------------------------------------------------------------
export function b3Solids(id is Id) returns Query
{
    return qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID);
}

export function b3Union(context is Context, id is Id, bodies is Query)
{
    if (size(evaluateQuery(context, bodies)) > 1)
    {
        opBoolean(context, id, { "tools" : bodies, "operationType" : BooleanOperationType.UNION });
    }
}

export function b3Finish(context is Context, bodies is Query, partName is string, rgb is array)
{
    b3Part(context, bodies, partName, material("Aluminum 5052-H32", ALU_DENSITY), rgb);
}

export function b3FinishSteel(context is Context, bodies is Query, partName is string)
{
    b3Part(context, bodies, partName, material("Stainless 304", STEEL_DENSITY), RGB_STEEL);
}

export function b3FinishTube(context is Context, bodies is Query, partName is string)
{
    b3Part(context, bodies, partName, material("Aluminum 6061", TUBE_DENSITY), RGB_TUBE);
}

function b3Part(context is Context, bodies is Query, partName is string, mat is Material, rgb is array)
{
    setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.NAME, "value" : partName });
    setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.MATERIAL, "value" : mat });
    setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.APPEARANCE,
                "value" : color(rgb[0], rgb[1], rgb[2]) });
}

// ===========================================================================
// B3_Reference.fs
// ===========================================================================
/*
 * B3 Reference: simple blocks for the surroundings, to check clearances.
 * The cabinet with its side panel, the bed-end wall, the mattress, the cab
 * door handle and the floor. Their names start with "REF". Add this feature
 * in a Part Studio of its own ("Surroundings"), so the stair's Part Studio
 * holds only the parts to make. The cabinet carries the mate connectors for
 * the brackets, the front angle and the step ledge.
 */
annotation { "Feature Type Name" : "B3 Reference" }
export const b3Reference = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const far = 30 * inch;
        const wallX = -WALL_GAP;
        b3Ref(context, id + "floor", vector(-far, -CABINET_WIDTH, -0.5 * inch), vector(far, far, 0 * inch), "REF floor");
        b3Ref(context, id + "cabinet", vector(wallX, -CABINET_WIDTH, 0 * inch), vector(wallX + CABINET_DEPTH, 0 * inch, CABINET_TOP_Z), "REF cabinet");
        b3Ref(context, id + "wall", vector(wallX - 1 * inch, 0 * inch, 0 * inch), vector(wallX, far, BED_PLATFORM_Z), "REF bed-end wall");
        b3Ref(context, id + "mattress", vector(-far, -CABINET_WIDTH, BED_PLATFORM_Z), vector(wallX, far, BED_PLATFORM_Z + MATTRESS_THICK), "REF mattress");
        b3Ref(context, id + "handle", vector(wallX, HANDLE_Y, HANDLE_Z - 0.5 * inch), vector(wallX + HANDLE_PROJECTION, HANDLE_Y + 4 * inch, HANDLE_Z + 0.5 * inch), "REF door handle");

        const cabinet = b3Solids(id + "cabinet");
        b3Mc(context, id + "mcBracketTop", cabinet, "REF cabinet", "Bracket, top tread", b3BracketJoint(TREAD_TOP));
        b3Mc(context, id + "mcBracketMiddle", cabinet, "REF cabinet", "Bracket, middle tread", b3BracketJoint(TREAD_MIDDLE));
        b3Mc(context, id + "mcFrontAngle", cabinet, "REF cabinet", "Front angle", b3FrontAngleJoint());
        b3Mc(context, id + "mcLedge", cabinet, "REF cabinet", "Step ledge", b3StepLedgeJoint());
    });

function b3Ref(context is Context, id is Id, lo is Vector, hi is Vector, partName is string)
{
    b3Box(context, id, lo, hi);
    setProperty(context, { "entities" : b3Solids(id), "propertyType" : PropertyType.NAME, "value" : partName });
    setProperty(context, { "entities" : b3Solids(id), "propertyType" : PropertyType.APPEARANCE,
                "value" : color(RGB_REF[0], RGB_REF[1], RGB_REF[2]) });
}

// ===========================================================================
// B3_Treads.fs
// ===========================================================================
/*
 * B3 Tread, 1/8" sheet-metal part: 18 x 5 5/8 skin with 2" lips bent down
 * at the x ends, bushing holes through both lips for the cabinet and outer
 * axles, and a 1/2" radius on both bottom corners of each lip (at the outer
 * end it keeps the lip clear of the rail bracket's web as it swings). The
 * lips run the skin's full width, so their bends need no reliefs. The stair
 * uses it twice; it is built once, where the top tread sits, and the
 * assembly places both.
 */
annotation { "Feature Type Name" : "B3 Tread" }
export const b3Treads = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const n = TREAD_TOP;
        const top = b3T(n);
        const holes = [
                b3Hole(CAB_AXLE_Y, top - CAB_AXLE_DROP, HOLE_DIA),
                b3Hole(OUT_AXLE_Y, top - OUT_AXLE_DROP, HOLE_DIA)
            ];
        b3Tray(context, id + "tray", b3GoingX(n) + TRAY_INSET, top, holes);

        const body = b3Solids(id + "tray");
        b3Finish(context, body, "Tread", RGB_ALU);
        b3Mc(context, id + "mcCab", body, "Tread", "Cabinet axle", b3CabAxleJoint(n));
        b3Mc(context, id + "mcOut", body, "Tread", "Outer axle", b3OutAxleJoint(n));
    });

// ===========================================================================
// B3_Brackets.fs
// ===========================================================================
/*
 * B3 Bracket, 3/16" sheet-metal part, used four times. The 5 1/8 x 2 web
 * has four M6 holes (countersinks not modeled); a hook-shaped ear is bent 90
 * degrees off each end to carry a tread axle. Two sit on the cabinet panel,
 * ears toward the room, with a stop pin through each ear. The other two are
 * the same part turned to face the cabinet and bolted inside the outer rail
 * with M6 x 16 flat-head screws and nyloc nuts; their stop-pin holes stay
 * empty. The ears run the web's full height and the hook starts past the
 * bend, so the bends need no extra reliefs. Built once, where the top
 * tread's cabinet bracket sits.
 */
annotation { "Feature Type Name" : "B3 Bracket" }
export const b3CabinetBrackets = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const n = TREAD_TOP;
        const top = b3T(n);
        const xg = b3GoingX(n);
        const faces = b3EarFaces(n);
        const webTop = top - BRACKET_TOP_DROP;
        const webBot = webTop - BRACKET_H;

        // Web, flat on the panel, with the screw row.
        var screws = [];
        for (var k = 0; k < size(SCREW_X); k += 1)
        {
            screws = append(screws, b3Hole(xg + SCREW_X[k], top - SCREW_DROP, SCREW_HOLE_DIA));
        }
        b3PrismXZ(context, id + "web", b3Rect(faces[0], webBot, faces[1], webTop), screws, 0 * inch, PLATE_T);

        // Ears, in (y, z).
        const axZ = top - CAB_AXLE_DROP;
        const ear = b3EarOutline(0 * inch, PLATE_T + EAR_W, PLATE_T + HOOK_U0, webBot, webTop, CAB_AXLE_Y, axZ);
        const earHoles = [
                b3Hole(CAB_AXLE_Y, axZ, HOLE_DIA),
                b3Hole(STOP_PIN_Y, top - STOP_PIN_DROP, STOP_PIN_DIA)
            ];
        const ranges = b3EarRanges(n);
        b3PrismYZ(context, id + "earBack", ear, earHoles, ranges[0][0], ranges[0][1]);
        b3PrismYZ(context, id + "earFront", ear, earHoles, ranges[1][0], ranges[1][1]);
        b3Union(context, id + "join", b3Solids(id));

        // Sheet metal: the web's panel face, then each ear's outer face.
        const earY = (PLATE_T + HOOK_U0) / 2;
        const earZ = webBot + BRACKET_H / 4;
        b3SheetMetal(context, id + "sm", b3Solids(id), [
                    vector(xg + GOING / 2, 0 * inch, earZ),
                    vector(faces[0], earY, earZ),
                    vector(faces[1], earY, earZ)
                ], PLATE_T, BEND_R_PLATE, K_PLATE);

        const body = b3Solids(id);
        const name = "Bracket";
        b3Finish(context, body, name, RGB_ALU_DARK);
        b3Mc(context, id + "mcCabinet", body, name, "Mounting face", b3BracketJoint(n));
        b3Mc(context, id + "mcAxle", body, name, "Axle", b3CabAxleJoint(n));
        b3Mc(context, id + "mcAxleTurned", body, name, "Axle, turned", b3BracketAxleTurnedJoint(n));
        b3Mc(context, id + "mcPinBack", body, name, "Stop pin, back", b3StopPinJoint(n, false));
        b3Mc(context, id + "mcPinFront", body, name, "Stop pin, front", b3StopPinJoint(n, true));
        for (var k = 0; k < size(SCREW_X); k += 1)
        {
            b3Mc(context, id + ("mcScrew" ~ k), body, name, "Screw " ~ (k + 1), b3BracketScrewJoint(n, k));
        }
    });

// ===========================================================================
// B3_OuterRail.fs
// ===========================================================================
/*
 * B3 Outer Rail, 3/16" sheet-metal part: stepped plate with a notch at the
 * bed-side bottom corner to clear the door handle by 1", 1" flanges turned
 * outward (+y) along the bed-side edge, the long lower edge, the foot and the
 * front edge, a hand slot, the step clip's rivet holes, and two rows of M6
 * holes for the rail brackets (the bracket part, turned to face the cabinet).
 * The bed-side and front flanges run the full length of their edges, so their
 * bends need no relief. The long flange stops 1/2" short of the notch corner,
 * with a bend relief there and the bare edge past it cut back inside the bend
 * line. Where two flanges meet at the foot, Onshape cuts a round corner
 * relief. Every flange's free corners are rounded. The notch's short edges and
 * the step tops are bare.
 *
 * Not modeled: the latch holes and the foot pad.
 */
annotation { "Feature Type Name" : "B3 Outer Rail" }
export const b3OuterRail = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const y0 = RAIL_Y;
        const y1 = RAIL_Y + PLATE_T;
        const fy1 = y1 + RAIL_FLANGE;
        const xm = GOING;
        const xf = 2 * GOING;
        const topStep = b3T(TREAD_TOP) - RAIL_STEP_DROP;
        const midStep = b3T(TREAD_MIDDLE) - RAIL_STEP_DROP;

        // The long lower edge runs from the foot through (RAIL_LINE_X, RAIL_LINE_Z)
        // up to the notch's front edge.
        const foot = vector(RAIL_FOOT_X, RAIL_FOOT_Z);
        const slope = (RAIL_LINE_Z - RAIL_FOOT_Z) / (RAIL_LINE_X - RAIL_FOOT_X);
        const notchLow = vector(RAIL_NOTCH_X, RAIL_FOOT_Z + (RAIL_NOTCH_X - RAIL_FOOT_X) * slope);

        // Plate outline in (x, z), same order as the B3 page, with its outside
        // corners rounded except where a flange's bend ends.
        const corners = [
                vector(0 * inch, topStep),
                vector(xm, topStep),
                vector(xm, midStep),
                vector(xf, midStep),
                vector(xf, RAIL_FOOT_Z),
                foot,
                notchLow,
                vector(RAIL_NOTCH_X, RAIL_BACK_Z),
                vector(0 * inch, RAIL_BACK_Z)
            ];
        const radii = [0, RAIL_CORNER_R, RAIL_STEP_R, 0, 0, 0, RAIL_NOTCH_R, RAIL_NOTCH_IN_R, 0];
        var holes = [b3Slot(vector(HAND_SLOT_X, HAND_SLOT_Z), HAND_SLOT_L, HAND_SLOT_H)];
        for (var i = 0; i < size(CLIP_RIVET_X); i += 1)
        {
            holes = append(holes, b3Hole(CLIP_RIVET_X[i], CLIP_RIVET_Z, RIVET_HOLE_DIA));
        }
        for (var n in [TREAD_TOP, TREAD_MIDDLE])
        {
            for (var k = 0; k < size(SCREW_X); k += 1)
            {
                const nut = b3RailNutJoint(n, k).origin;
                holes = append(holes, b3Hole(nut[0], nut[2], SCREW_HOLE_DIA));
            }
        }
        b3PrismXZ(context, id + "plate", b3Rounded(corners, radii), holes, y0, y1);

        // Flanges along their edges (listed so the plate is on the left), turned
        // outward, with their free corners rounded. The bed-side and front ones run
        // from corner to corner; the long one stops RAIL_FLANGE_STOP short of the
        // notch corner.
        const longDir = (foot - notchLow) / norm(foot - notchLow);
        const longTop = notchLow + longDir * RAIL_FLANGE_STOP;
        const flanges = [
                [vector(0 * inch, topStep), vector(0 * inch, RAIL_BACK_Z)],
                [longTop, foot],
                [foot, vector(xf, RAIL_FOOT_Z)],
                [vector(xf, RAIL_FOOT_Z), vector(xf, midStep)]
            ];
        var outside = [vector(xm + GOING / 2, y0, CLIP_RIVET_Z + 2.5 * inch)];
        for (var i = 0; i < size(flanges); i += 1)
        {
            const f = flanges[i];
            b3Flange(context, id + ("flange" ~ i), f[0], f[1], y0, fy1, RAIL_FLANGE_TIP_R, RAIL_FLANGE_TIP_R);
            const mid = (f[0] + f[1]) / 2;
            outside = append(outside, vector(mid[0], (y1 + fy1) / 2, mid[1]));
        }
        b3Union(context, id + "join", b3Solids(id));

        // Bend relief where the long flange stops, cut into the plate. Past it, the
        // edge is cut back inside the bend line until it runs into the notch's edge.
        const inward = vector(-longDir[1], longDir[0]);
        const bareInset = b3BareInset(PLATE_T, BEND_R_PLATE, K_PLATE);
        const bareLength = (RAIL_NOTCH_X - longTop[0] - inward[0] * bareInset) / (-longDir[0]) + 0.1 * inch;
        b3PrismXZ(context, id + "relief", b3ReliefPath(longTop, -longDir, inward, PLATE_T, BEND_R_PLATE, K_PLATE, bareLength), [],
            y0 - 0.05 * inch, y1 + 0.05 * inch);
        b3Subtract(context, id + "cutRelief", qSubtraction(b3Solids(id), b3Solids(id + "relief")), b3Solids(id + "relief"));

        b3SheetMetal(context, id + "sm", b3Solids(id), outside, PLATE_T, BEND_R_PLATE, K_PLATE);

        const rail = b3Solids(id);
        const name = "Outer rail";
        b3Finish(context, rail, name, RGB_ALU);
        b3Mc(context, id + "mcTop", rail, name, "Top tread bracket", b3RailBracketJoint(TREAD_TOP));
        b3Mc(context, id + "mcMiddle", rail, name, "Middle tread bracket", b3RailBracketJoint(TREAD_MIDDLE));
        b3Mc(context, id + "mcClip", rail, name, "Step clip", b3StepClipJoint());
        for (var k = 0; k < size(SCREW_X); k += 1)
        {
            b3Mc(context, id + ("mcNutTop" ~ k), rail, name, "Nut, top " ~ (k + 1), b3RailNutJoint(TREAD_TOP, k));
            b3Mc(context, id + ("mcNutMiddle" ~ k), rail, name, "Nut, middle " ~ (k + 1), b3RailNutJoint(TREAD_MIDDLE, k));
        }
    });

// ===========================================================================
// B3_StepClip.fs
// ===========================================================================
/*
 * B3 Step Clip, 1/8" sheet-metal part: small angle riveted inside the outer
 * rail. Its keyhole takes the hook pin on the back end of the hook-on step's
 * outer leg axle. The free corners of both legs are rounded.
 */
annotation { "Feature Type Name" : "B3 Step Clip" }
export const b3StepClip = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const x1 = 2 * GOING;
        const z0 = CLIP_Z0;
        const z1 = CLIP_Z0 + CLIP_H;
        const r = CLIP_CORNER_R;

        // Rail leg, against the rail's inner face, with the rivet holes.
        var rivets = [];
        for (var i = 0; i < size(CLIP_RIVET_X); i += 1)
        {
            rivets = append(rivets, b3Hole(CLIP_RIVET_X[i], CLIP_RIVET_Z, RIVET_HOLE_DIA));
        }
        b3PrismXZ(context, id + "railLeg", b3Rounded(b3Rect(CLIP_X0, z0, x1, z1), [r, 0, 0, r]), rivets, RAIL_Y - SHEET_T, RAIL_Y);

        // Keyhole leg, outer face flush with x = 12.
        b3PrismYZ(context, id + "keyLeg", b3Rounded(b3Rect(CLIP_KEY_LEG_Y0, z0, RAIL_Y, z1), [r, 0, 0, r]),
            [b3Keyhole(CLIP_KEYHOLE_Y, CLIP_KEYHOLE_Z, CLIP_KEYHOLE_END_Z)], x1 - SHEET_T, x1);
        b3Union(context, id + "join", b3Solids(id));

        // Sheet metal: the face against the rail, then the keyhole leg's outer face.
        b3SheetMetal(context, id + "sm", b3Solids(id), [
                    vector((CLIP_RIVET_X[0] + CLIP_RIVET_X[1]) / 2, RAIL_Y, z0 + CLIP_H / 4),
                    vector(x1, (CLIP_KEY_LEG_Y0 + CLIP_KEYHOLE_Y) / 2, z0 + CLIP_H / 4)
                ], SHEET_T, BEND_R_SHEET, K_SHEET);

        const clip = b3Solids(id);
        b3Finish(context, clip, "Step clip", RGB_ALU_DARK);
        b3Mc(context, id + "mcRail", clip, "Step clip", "Outer rail", b3StepClipJoint());
    });

// ===========================================================================
// B3_PivotHardware.fs
// ===========================================================================
/*
 * B3 Pivot Hardware, one of each part, for checking fit and folded
 * clearances in the assembly:
 *   Tread axle (4 used) and step axle (2 used; the back end is the hook
 *   pin), 12 mm aluminum tube with a 5 mm bore tapped M6 at both ends.
 *   M6 fender washer and M6 button-head screw (12 each, one on each axle end).
 *   Stop pin (4 used), 3/16" pin through each cabinet bracket ear.
 *   M6 x 16 flat-head screw and M6 nyloc nut (8 each), bolting the two rail
 *   brackets inside the outer rail.
 * Each is built where its first use sits: the top tread's cabinet axle, the
 * step's cabinet-side axle, the washer and screw on the top tread's cabinet
 * axle at the bed end, the top cabinet bracket's back stop pin, and the
 * first screw of the top rail bracket with its nut.
 * Bushings, thrust washers and wave washers aren't modeled.
 */
annotation { "Feature Type Name" : "B3 Pivot Hardware" }
export const b3PivotHardware = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const tread = b3CabAxleJoint(TREAD_TOP);
        b3Axle(context, id + "treadAxle", tread, TREAD_AXLE_LEN, "Tread axle");
        b3Axle(context, id + "stepAxle", b3StepCabAxleJoint(), STEP_AXLE_X1 - STEP_AXLE_X0, "Step axle");

        // Washer and screw head, stacked out from the axle's bed-end tip.
        const p = tread.origin;
        const x0 = p[0];
        const w = x0 - END_WASHER_T;
        b3CylX(context, id + "washer", p[1], p[2], w, x0, END_WASHER_DIA);
        const washer = b3Solids(id + "washer");
        b3FinishSteel(context, washer, "M6 fender washer");
        b3Mc(context, id + "mcWasherAxle", washer, "M6 fender washer", "Axle", tread);
        const under = b3AxleJoint(w, p[1], p[2]);
        b3Mc(context, id + "mcWasherScrew", washer, "M6 fender washer", "Screw", under);

        b3CylX(context, id + "screw", p[1], p[2], w - END_HEAD_H, w, END_HEAD_DIA);
        const screw = b3Solids(id + "screw");
        b3FinishSteel(context, screw, "M6 button-head screw");
        b3Mc(context, id + "mcScrew", screw, "M6 button-head screw", "Washer", under);

        // Stop pin: flush with the bracket ear's inside face, sticking out under the lip.
        const pin = b3StopPinJoint(TREAD_TOP, false);
        const q = pin.origin;
        b3CylX(context, id + "pin", q[1], q[2], q[0] - PLATE_T - STOP_PIN_OUT, q[0], STOP_PIN_DIA);
        b3FinishSteel(context, b3Solids(id + "pin"), "Stop pin");
        b3Mc(context, id + "mcPin", b3Solids(id + "pin"), "Stop pin", "Bracket", pin);

        // Flat-head screw: 90 degree head flush with the bracket web's ear side, shank through the rail.
        const head = b3OnRail(TREAD_TOP, b3BracketScrewJoint(TREAD_TOP, 0));
        const s0 = head.origin;
        const along = head.zAxis;
        const headH = (FH_HEAD_DIA - FH_DIA) / 2;
        fCone(context, id + "fh" + "head", { "bottomCenter" : b3V(s0), "topCenter" : b3V(s0 + along * headH),
                    "bottomRadius" : FH_HEAD_DIA / 2, "topRadius" : FH_DIA / 2 });
        fCylinder(context, id + "fh" + "shank", { "bottomCenter" : b3V(s0 + along * headH), "topCenter" : b3V(s0 + along * FH_LEN),
                    "radius" : FH_DIA / 2 });
        b3Union(context, id + "fh" + "join", b3Solids(id + "fh"));
        const fh = b3Solids(id + "fh");
        b3FinishSteel(context, fh, "M6 flat-head screw");
        b3Mc(context, id + "mcFh", fh, "M6 flat-head screw", "Head", head);

        // Nyloc nut on the rail's outer face, a hex prism around the screw.
        const nutJoint = b3RailNutJoint(TREAD_TOP, 0);
        const c = nutJoint.origin;
        var hex = [];
        for (var i = 0; i < 6; i += 1)
        {
            const a = (30 + 60 * i) * degree;
            hex = append(hex, vector(c[0] + NUT_AF / sqrt(3) * cos(a), c[2] + NUT_AF / sqrt(3) * sin(a)));
        }
        b3PrismXZ(context, id + "nut", hex, [b3Hole(c[0], c[2], FH_DIA)], c[1], c[1] + NUT_H);
        b3FinishSteel(context, b3Solids(id + "nut"), "M6 nyloc nut");
        b3Mc(context, id + "mcNut", b3Solids(id + "nut"), "M6 nyloc nut", "Rail", nutJoint);
    });

// A tube axle of length len from the joint at its bed-end tip, with a mate
// connector on each tip pointing out of the tube.
function b3Axle(context is Context, id is Id, tip is map, len is ValueWithUnits, partName is string)
{
    const p = tip.origin;
    b3TubeX(context, id + "tube", p[1], p[2], p[0], p[0] + len, AXLE_DIA, AXLE_BORE);
    const tube = b3Solids(id + "tube");
    b3FinishTube(context, tube, partName);
    b3Mc(context, id + "mcBack", tube, partName, "Back end", tip);
    b3Mc(context, id + "mcFront", tube, partName, "Front end",
        b3Joint(vector(p[0] + len, p[1], p[2]), vector(1, 0, 0), vector(0, 1, 0)));
}

// ===========================================================================
// B3_FrontAngle.fs
// ===========================================================================
/*
 * B3 Front Angle, 1/8" sheet-metal part, on the cabinet's front post. The
 * panel leg takes three screws into the post and stops at 16 1/2" to clear
 * the middle bracket. Above that the outward leg's inner edge steps back by a
 * full relief depth, which is the bend's relief and keeps the bend line clear
 * of the bare edge. The outward leg is flush with the front edge and carries
 * the keyhole for the hook-on step's cabinet-side pin. Corners are rounded
 * 1/4", and 1/2" on the outward leg's top outer corner, which faces the entry.
 * Not modeled: the keeper holes (drill to suit the latch).
 */
annotation { "Feature Type Name" : "B3 Front Angle" }
export const b3FrontAngle = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const r = FA_CORNER_R;
        var screws = [];
        for (var i = 0; i < size(FA_SCREW_Z); i += 1)
        {
            screws = append(screws, b3Hole(FA_SCREW_X, FA_SCREW_Z[i], FA_SCREW_HOLE_DIA));
        }
        b3PrismXZ(context, id + "panelLeg", b3Rounded(b3Rect(FA_PANEL_LEG_X0, FA_BOTTOM_Z, FA_X1, FA_PANEL_LEG_TOP), [r, 0, 0, r]),
            screws, 0 * inch, SHEET_T);

        // Outward leg in (y, z), stepped back above the panel leg's top.
        const stepBack = b3ReliefDepth(SHEET_T, BEND_R_SHEET, K_SHEET);
        const outLeg = [
                vector(0 * inch, FA_BOTTOM_Z),
                vector(FA_OUT_LEG, FA_BOTTOM_Z),
                vector(FA_OUT_LEG, FA_TOP_Z),
                vector(stepBack, FA_TOP_Z),
                vector(stepBack, FA_PANEL_LEG_TOP),
                vector(0 * inch, FA_PANEL_LEG_TOP)
            ];
        b3PrismYZ(context, id + "outLeg", b3Rounded(outLeg, [0, r, FA_ENTRY_R, r, 0, 0]),
            [b3Keyhole(FA_KEYHOLE_Y, FA_KEYHOLE_Z, FA_KEYHOLE_END_Z)], FA_X1 - SHEET_T, FA_X1);
        b3Union(context, id + "join", b3Solids(id));

        // Sheet metal: the panel leg's face on the panel, then the outward leg's outer face.
        b3SheetMetal(context, id + "sm", b3Solids(id), [
                    vector((FA_PANEL_LEG_X0 + FA_SCREW_X) / 2, 0 * inch, FA_BOTTOM_Z + 1 * inch),
                    vector(FA_X1, FA_OUT_LEG / 2, FA_BOTTOM_Z + 1 * inch)
                ], SHEET_T, BEND_R_SHEET, K_SHEET);

        const body = b3Solids(id);
        const name = "Front angle";
        b3Finish(context, body, name, RGB_ALU_DARK);
        b3Mc(context, id + "mcCabinet", body, name, "Cabinet", b3FrontAngleJoint());
        b3Mc(context, id + "mcStep", body, name, "Hook-on step", b3StepCabAxleJoint());
    });

// ===========================================================================
// B3_StepLedge.fs
// ===========================================================================
/*
 * B3 Step Ledge, 1/8" sheet-metal part: 6" angle on the panel at the bed
 * end. The folded hook-on step stands on end on its 2 1/2" shelf. Two #8
 * screws through the back leg (countersinks not modeled). The shelf's front
 * corners, at ankle height, are rounded 1/2"; the back leg's bottom corners
 * 1/4".
 */
annotation { "Feature Type Name" : "B3 Step Ledge" }
export const b3StepLedge = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const top = LEDGE_TOP_Z;
        const shelf = b3Rounded(b3Rect(0 * inch, 0 * inch, LEDGE_LEN, LEDGE_SHELF), [0, 0, LEDGE_SHELF_R, LEDGE_SHELF_R]);
        b3PrismXY(context, id + "shelf", shelf, [], top - SHEET_T, top);

        var screws = [];
        for (var i = 0; i < size(LEDGE_SCREW_X); i += 1)
        {
            screws = append(screws, b3Hole(LEDGE_SCREW_X[i], LEDGE_SCREW_Z, LEDGE_SCREW_DIA));
        }
        const leg = b3Rounded(b3Rect(0 * inch, top - LEDGE_LEG_H, LEDGE_LEN, top), [LEDGE_LEG_R, LEDGE_LEG_R, 0, 0]);
        b3PrismXZ(context, id + "leg", leg, screws, 0 * inch, SHEET_T);
        b3Union(context, id + "join", b3Solids(id));

        // Sheet metal: the back leg's face on the panel, then the shelf's top.
        b3SheetMetal(context, id + "sm", b3Solids(id), [
                    vector(LEDGE_LEN / 2, 0 * inch, LEDGE_SCREW_Z),
                    vector(LEDGE_LEN / 2, LEDGE_SHELF / 2, top)
                ], SHEET_T, BEND_R_SHEET, K_SHEET);

        const body = b3Solids(id);
        b3Finish(context, body, "Step ledge", RGB_ALU_DARK);
        b3Mc(context, id + "mcCabinet", body, "Step ledge", "Cabinet", b3StepLedgeJoint());
    });

// ===========================================================================
// B3_HookOnStep.fs
// ===========================================================================
/*
 * B3 Hook-on Step: a 1/8" sheet-metal tray like the treads and two 3/16"
 * sheet-metal legs. Each leg is a web with an ear bent inboard at each end;
 * the ears turn on an axle through the tray lips. An ear's bend runs from 1"
 * below its axle hole up to the web's top edge, so the hole sits in the ear
 * with the bend beside it, and the ear's top runs straight from the web's top
 * edge onto the round over the hole. Below the ear, a bend relief is cut into
 * the web and the web's edge is cut back inside the bend line. The axle's back
 * end is a pin that drops into a keyhole: the front angle for the
 * cabinet-side leg, the step clip for the outer leg. Built open; the legs fold
 * flat in two layers inside the lips. Not modeled: the rubber boots.
 */
annotation { "Feature Type Name" : "B3 Hook-on Step" }
export const b3HookOnStep = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const top = b3T(HOOK_STEP);
        const holes = [
                b3Hole(STEP_CAB_AXLE_Y, STEP_CAB_AXLE_Z, HOLE_DIA),
                b3Hole(STEP_OUT_AXLE_Y, STEP_OUT_AXLE_Z, HOLE_DIA)
            ];
        b3Tray(context, id + "tray", b3GoingX(HOOK_STEP) + TRAY_INSET, top, holes);
        const tray = b3Solids(id + "tray");
        const name = "Hook-on step tray";
        b3Finish(context, tray, name, RGB_STEP);
        b3Mc(context, id + "mcCab", tray, name, "Cabinet-side axle", b3StepCabAxleJoint());
        b3Mc(context, id + "mcOut", tray, name, "Outer axle", b3StepOutAxleJoint());

        // Cabinet-side leg: web y 3/8 to 9/16, ears reach toward +y.
        const cabIn = STEP_LEG_CAB_Y0 + PLATE_T;
        b3StepLeg(context, id + "cabLeg", STEP_LEG_CAB_Y0, cabIn, cabIn + STEP_EAR_W,
            b3StepCabAxleJoint(), "Hook-on step leg, cabinet side");

        // Outer leg: web y 18 3/16 to 18 3/8, ears reach toward -y.
        const outIn = STEP_LEG_OUT_Y1 - PLATE_T;
        b3StepLeg(context, id + "outLeg", STEP_LEG_OUT_Y1, outIn, outIn - STEP_EAR_W,
            b3StepOutAxleJoint(), "Hook-on step leg, outer");
    });

// One leg. yOut and yIn are the web's faces; the ear runs from the web to
// yFar below the axle.
function b3StepLeg(context is Context, id is Id, yOut is ValueWithUnits, yIn is ValueWithUnits, yFar is ValueWithUnits,
    axle is map, partName is string)
{
    const axY = axle.origin[1];
    const axZ = axle.origin[2];
    const faces = b3EarFaces(HOOK_STEP);
    const ylo = min(yOut, yIn);
    const yhi = max(yOut, yIn);
    const top = STEP_LEG_TOP_Z;
    const earLo = axZ - STEP_EAR_DROP;

    // Web in (x, z). At each end the ear's bend runs from earLo up to the top
    // edge. Below it, a bend relief, then the edge cut back inside the bend line.
    const x0 = faces[0];
    const x1 = faces[1];
    const d = b3ReliefDepth(PLATE_T, BEND_R_PLATE, K_PLATE);
    const e = b3BareInset(PLATE_T, BEND_R_PLATE, K_PLATE);
    const zr = earLo - RELIEF_W_SCALE * PLATE_T;
    const r = LEG_CORNER_R;
    const web = [
            vector(x0 + e, STEP_LEG_BOTTOM_Z),
            vector(x1 - e, STEP_LEG_BOTTOM_Z),
            vector(x1 - e, zr),
            vector(x1 - d, zr),
            vector(x1 - d, earLo),
            vector(x1, earLo),
            vector(x1, top),
            vector(x0, top),
            vector(x0, earLo),
            vector(x0 + d, earLo),
            vector(x0 + d, zr),
            vector(x0 + e, zr)
        ];
    b3PrismXZ(context, id + "web", b3Rounded(web, [r, r, r, 0, 0, 0, 0, 0, 0, 0, 0, r]), [], ylo, yhi);

    // Ear in (y, z): full width from earLo up to the axle, a round of EAR_HOOK_R
    // on the hole, then a straight edge from the round's top side to the web's
    // top edge, touching the round.
    const c = vector(axY, axZ);
    const corner = vector(yOut, top);
    const toCorner = corner - c;
    const reach = acos(EAR_HOOK_R / norm(toCorner));
    const toCornerAngle = atan2(toCorner[1], toCorner[0]);
    const t1 = c + vector(cos(toCornerAngle - reach), sin(toCornerAngle - reach)) * EAR_HOOK_R;
    const t2 = c + vector(cos(toCornerAngle + reach), sin(toCornerAngle + reach)) * EAR_HOOK_R;
    const touch = t1[1] > t2[1] ? t1 : t2;
    const farAngle = yFar > axY ? 0 * degree : 180 * degree;
    const midAngle = (farAngle + atan2(touch[1] - axZ, touch[0] - axY)) / 2;
    const ear = concatenateArrays([
                [vector(yOut, earLo)],
                b3Corner(vector(yOut, earLo), vector(yFar, earLo), vector(yFar, axZ), r),
                [vector(yFar, axZ), { "mid" : c + vector(cos(midAngle), sin(midAngle)) * EAR_HOOK_R, "end" : touch }, corner]
            ]);
    const holes = [b3Hole(axY, axZ, HOLE_DIA)];
    const ranges = b3EarRanges(HOOK_STEP);
    b3PrismYZ(context, id + "earBack", ear, holes, ranges[0][0], ranges[0][1]);
    b3PrismYZ(context, id + "earFront", ear, holes, ranges[1][0], ranges[1][1]);
    b3Union(context, id + "join", b3Solids(id));

    // Sheet metal: the web's outer face, then each ear's outer face.
    const earY = (yOut + yFar) / 2;
    const midX = (faces[0] + faces[1]) / 2;
    b3SheetMetal(context, id + "sm", b3Solids(id), [
                vector(midX, yOut, STEP_LEG_BOTTOM_Z + 1 * inch),
                vector(faces[0], earY, earLo + STEP_EAR_DROP / 4),
                vector(faces[1], earY, earLo + STEP_EAR_DROP / 4)
            ], PLATE_T, BEND_R_PLATE, K_PLATE);

    b3Finish(context, b3Solids(id), partName, RGB_STEP);
    b3Mc(context, id + "mcAxle", b3Solids(id), partName, "Axle", axle);
}
